#!/usr/bin/env python3
"""Generate 500 ShareGPT knowledge samples for Lyra batch-08-B.

Categories: history + arts_and_humanities (sibling B of phase 09.3-01).
Reads templates/knowledge-topics-v2.yaml, deterministically shuffles all
(topic, sub_angle) tuples with seed 1009031B, and writes the first 500 as
inline-authored Q/A pairs to:
  datasets/knowledge/raw-09.3/batch-08-B-knowledge.jsonl
"""
import hashlib
import json
import os
import random
import re

YAML_PATH = "/Users/lakshman/Documents/Lyra/templates/knowledge-topics-v2.yaml"
OUT_PATH = "/Users/lakshman/Documents/Lyra/datasets/knowledge/raw-09.3/batch-08-B-knowledge.jsonl"

SYSTEM_PROMPT = (
    "You are a knowledgeable assistant. Provide accurate, clear answers.\n"
    "For complex topics, break your explanation into steps.\n"
    "For simple factual questions, be concise."
)

SUB_ANGLES = ["definition", "mechanism", "significance", "comparison", "example", "misconception"]


def load_topics():
    text = open(YAML_PATH).read()

    def grab(name):
        pat = rf"^  {name}:\s*\n((?:    .*\n|    \n|\s*\n)*?)(?=^  \w|\Z)"
        m = re.search(pat, text, re.MULTILINE)
        if not m:
            return []
        return [
            line.strip()[2:].strip()
            for line in m.group(1).splitlines()
            if line.strip().startswith("- ")
        ]

    return grab("history"), grab("arts_and_humanities")


# ---------------------------------------------------------------------------
# FACTS: per-topic content blocks
#
# Each entry maps a topic -> dict of factual content fields:
#   summary    : 2-3 sentence definition with key dates/names/places
#   how        : the mechanism / process / sequence of events (3-5 sentences)
#   why        : significance and lasting impact (2-4 sentences)
#   versus     : (related thing, distinguishing facts) tuple
#   case       : a concrete worked example, person, or episode (3-5 sentences)
#   myth       : a common misconception and its correction (2-3 sentences)
#
# The angle-specific generator below composes 6 distinct, Sonnet-quality
# answers by selecting and connecting these fields with natural connective
# prose (no numbered bullets, mirroring explanation-batch-01.jsonl style).
# ---------------------------------------------------------------------------

